// Real API lifecycle tests. Use a tag-scoped key; cleanup touches only names
// generated by this test. EXE_TOKEN_FILE accepts a bare token or token JSON.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import exedev, { VM, VMReadyError, ExeAPIError, SSHStreamError } from "../dist/index.js";

const tokenFile = process.env.EXE_TOKEN_FILE || join(homedir(), ".config", "exedev", "sdk-test-token");
const tag = process.env.EXE_TEST_TAG || "sdk-test";
function loadToken() {
  if (process.env.EXE_TOKEN) return process.env.EXE_TOKEN.trim();
  try {
    const content = readFileSync(tokenFile, "utf8").trim();
    return content.startsWith("{") ? JSON.parse(content).token : content;
  } catch { return ""; }
}
const token = loadToken();
const skip = process.env.EXE_SKIP_INTEGRATION ? "EXE_SKIP_INTEGRATION is set" : false;
const skipSSH = process.env.EXE_SKIP_SSH_INTEGRATION ? "EXE_SKIP_SSH_INTEGRATION is set" : false;
const ready = skipSSH ? { waitUntil: "created" } : {};

test("integration", { skip, timeout: 300_000 }, async (t) => {
  assert.ok(token, `no API token: set EXE_TOKEN or EXE_TOKEN_FILE (default ${tokenFile}), or EXE_SKIP_INTEGRATION=1`);
  const exe = exedev({ token, baseURL: process.env.EXE_BASE_URL });
  const name = `sdk-test-${Date.now().toString(36)}`;
  const renamed = `${name}-r`;
  const copyName = `${name}-c`;
  const missing = `${name}-missing`;
  let vm;
  t.after(async () => {
    for (const cleanupName of new Set([copyName, renamed, vm?.name, name].filter(Boolean))) {
      try { await exe.vm(cleanupName).rm({ signal: AbortSignal.timeout(30_000) }); }
      catch (err) {
        if (!(err instanceof ExeAPIError) || !/not found/.test(err.details().body)) throw err;
      }
    }
  });
  await t.test("whoami", async () => {
    const me = await exe.whoami();
    assert.match(me.email, /@/);
    assert.ok(Array.isArray(me.ssh_keys));
  });
  await t.test(skipSSH ? "new (SSH readiness explicitly skipped)" : "new returns an SSH-ready VM; first user command needs no retry", async () => {
    try {
      vm = await exe.new({ name, comment: "sdk integration test", signal: t.signal, ...ready });
    } catch (err) {
      if (err instanceof VMReadyError) vm = err.vm;
      // Opt in to server diagnostics for these non-secret test commands.
      const cause = err.cause ?? err;
      t.diagnostic(JSON.stringify({ error: cause.message, details: cause.details?.() }));
      throw err;
    }
    assert.ok(vm instanceof VM);
    assert.equal(vm.name, name);
    assert.ok(vm.tags.includes(tag), `expected tag ${tag}, got ${JSON.stringify(vm.tags)}`);
    if (skipSSH) return;
    const res = await vm.ssh("echo to-stdout; echo to-stderr >&2; exit 7");
    assert.equal(res.exitCode, 7);
    assert.equal(res.stdout, "to-stdout\n");
    assert.equal(res.stderr, "to-stderr\n");
  });
  await t.test("ls and refresh return usable VM objects", async () => {
    const listed = (await exe.ls()).find((v) => v.name === name);
    assert.ok(listed instanceof VM);
    assert.ok(listed.tags.includes(tag));
    assert.equal(listed.info.comment, "sdk integration test");
    assert.ok(Math.abs(Date.parse(listed.info.createdAt) - Date.now()) < 3_600_000);
    assert.equal(await vm.refresh(), vm);
    assert.match(vm.httpsUrl, /^https:\/\//);
    if (!skipSSH) assert.equal((await listed.ssh("true")).exitCode, 0);
  });
  await t.test("streaming without retaining output", { skip: skipSSH }, async () => {
    const chunks = [];
    const res = await vm.ssh("echo a; echo b", { capture: false, onStdout: (s) => { chunks.push(s); } });
    assert.equal(chunks.join(""), "a\nb\n");
    assert.equal(res.captured, false);
    assert.equal(res.stdout, "");
  });
  await t.test("output limits stop capture and binary output is unchanged", { skip: skipSSH }, async () => {
    const result = await vm.ssh("head -c 1024 /dev/zero");
    assert.deepEqual(result.stdoutBytes, new Uint8Array(1024));
    await assert.rejects(vm.ssh("head -c 16384 /dev/zero", { maxOutputBytes: 128 }),
      (err) => err instanceof SSHStreamError && err.code === "output_limit");
  });
  await t.test("cancellation preserves its reason with a live command", { skip: skipSSH }, async () => {
    const controller = new AbortController();
    const reason = new DOMException("test cancellation", "AbortError");
    await assert.rejects(vm.ssh("yes", {
      capture: false, signal: controller.signal, onStdout: () => controller.abort(reason),
    }), (err) => err === reason);
  });
  await t.test(skipSSH ? "cp (SSH readiness explicitly skipped)" : "cp returns an independently usable SSH-ready VM", async () => {
    const copy = await vm.cp({ name: copyName, signal: t.signal, ...ready });
    assert.ok(copy instanceof VM);
    assert.equal(copy.name, copyName);
    if (!skipSSH) assert.equal((await copy.ssh("printf copy-ready")).stdout, "copy-ready");
    assert.deepEqual(await copy.rm(), { deleted: [copyName], failed: [] });
  });
  await t.test("stat and VM-bound sharing", async () => {
    const st = await vm.stat();
    assert.equal(st.name, name);
    assert.ok(st.points === null || Array.isArray(st.points));
    assert.equal((await vm.shareShow()).vm_name, name);
  });
  await t.test("account methods stay on the client", async () => {
    assert.ok(Array.isArray((await exe.sshKeyList()).ssh_keys));
    await assert.rejects(exe.billingPlan(), (err) => err instanceof ExeAPIError && err.status === 403);
  });
  await t.test(skipSSH ? "restart (SSH readiness explicitly skipped)" : "restart waits for SSH", async () => {
    assert.equal(await vm.restart({ signal: t.signal, ...ready }), vm);
    if (!skipSSH) assert.equal((await vm.ssh("true")).exitCode, 0);
  });
  await t.test("rename updates subsequent operations on the same object", async () => {
    assert.equal(await vm.rename(renamed), vm);
    assert.equal(vm.name, renamed);
    if (!skipSSH) assert.equal((await vm.ssh("printf renamed")).stdout, "renamed");
    assert.equal((await vm.refresh()).name, renamed);
    assert.deepEqual((await exe.ls(renamed)).map((v) => v.name), [renamed]);
  });
  await t.test("rm and errors", async () => {
    assert.deepEqual(await vm.rm(), { deleted: [renamed], failed: [] });
    assert.ok(!(await exe.ls()).some((v) => v.name === renamed));
    await assert.rejects(exe.vm(missing).rm(), ExeAPIError);
    await assert.rejects(exe.vm(missing).restart(), (err) => err instanceof ExeAPIError && err.status === 422);
  });
});
